public void onEvent(ProductChangeEvent event) {
    long currentVersion = checkpointRepository.getVersion(event.getProductId());
    if (event.getVersion() <= currentVersion) {
        return;
    }

    projectEventToSearchIndex(event);
    checkpointRepository.advanceVersionIfNewer(event.getProductId(), currentVersion, event.getVersion());
}

long getVersion(String productId);

default boolean advanceVersionIfNewer(String productId, long expectedVersion, long newVersion) {
    if (getVersion(productId) != expectedVersion || newVersion <= expectedVersion) {
        return false;
    }
    saveVersion(productId, newVersion);
    return true;
}

